// Precomputed base64 PNG data for PDF report headers.
// Kept as plain constants (not Vite asset imports) so jsPDF report
// generation stays a simple synchronous function - no fetch/FileReader
// round-trip needed to turn an asset URL into image data.
//
// REMAN_LOGO_PNG / BRAXON_ICON_PNG were hand-generated from "logo reman.png"
// and src-tauri/icons/128x128.png. BRAXON_WORDMARK_PNG is regenerated from the
// LogoName component by `npm run gen:logos` (scripts/gen-logo-assets.mjs) -
// re-run that if the wordmark art in src/components/Logo.tsx ever changes.

export const REMAN_LOGO_PNG = "data:image/png;base64,";

export const BRAXON_ICON_PNG = "data:image/png;base64,";

// BRAXON wordmark, white on transparent — regenerated by scripts/gen-logo-assets.mjs
export const BRAXON_WORDMARK_PNG = "data:image/png;base64,";
